def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Validate input types
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser instances")
    for name, parser in subparsers.items():
        if not isinstance(name, str):
            raise TypeError("subparser names must be strings")
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError("subparser values must be ArgumentParser instances")

    parsed = {}
    claimed_args = set()

    for name, parser in subparsers.items():
        try:
            ns, remaining = parser.parse_known_args(unparsed_arguments)
        except SystemExit as e:
            # argparse may call sys.exit on error; convert to RuntimeError
            raise RuntimeError(f"Argument parsing failed for subparser '{name}': {e}") from e
        except Exception as e:
            raise RuntimeError(f"Error parsing arguments for subparser '{name}': {e}") from e

        parsed[name] = ns

        # Arguments that this parser recognized are those not in the remaining list
        # Use set to avoid duplicates across subparsers
        recognized = set(arg for arg in unparsed_arguments if arg not in remaining)
        claimed_args.update(recognized)

    # Remaining arguments are those not claimed by any subparser
    remaining_args = [arg for arg in unparsed_arguments if arg not in claimed_args]

    return parsed, remaining_args

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate max_results
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an integer, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError(f"max_results must be a positive integer, got {max_results}")

    # Handle None response as empty list
    if response is None:
        response = []

    # Validate response type
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")

    # Generator logic
    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        # Re-raise with context
        raise RuntimeError(f"Error while paging through response: {exc}") from exc

