                self.result.append(f'<{tag}{attrs_str}>')

        def handle_startendtag(self, tag, attrs):
            attrs_str = ''.join(f' {name}="{value}"' for name, value in attrs)
            self.result.append(f'<{tag}{attrs_str} />')

        def handle_endtag(self, tag):
            self.result.append(f'</{tag}>')

        def handle_data(self, data):
            # Linkify URLs in data
            def repl(match):
                url = match.group(0)
                href = url
                if url.lower().startswith('www.'):
                    href = 'http://' + url
                return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'
            processed = url_pattern.sub(repl, data)
            self.result.append(processed)

        def handle_comment(self, data):
            self.result.append(f'<!--{data}-->')

        def handle_entityref(self, name):
            self.result.append(f'&{name};')

        def handle_charref(self, name):
            self.result.append(f'&#{name};')

    parser = LinkProcessor()
    parser.feed(text)
    parser.close()
    return ''.join(parser.result)

