                # If False, skip adding the flag
            elif value is None:
                # Skip None values
                continue
            else:
                cmd.extend([key, str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            capture_output=True,
            text=True,
            check=True,
